#include<bits/stdc++.h>
using namespace std;
int main(){
    int N;
    scanf("%d",&N);
    vector<int>par(N+1,0);
    vector<vector<int>>ch(N+1);
    for(int i=2;i<=N;i++){
        scanf("%d",&par[i]);
        ch[par[i]].push_back(i);
    }
    // Collect leaves in DFS order to get ring
    vector<int>leaves;
    function<void(int)>dfs=[&](int u){
        if(ch[u].empty()){leaves.push_back(u);return;}
        for(int c:ch[u])dfs(c);
    };
    dfs(1);
    int L=leaves.size();
    if(L<=1||N<=4){
        // Single bag
        printf("1\n%d",N);
        for(int i=1;i<=N;i++)printf(" %d",i);
        printf("\n");
        return 0;
    }
    // Ring: leaves[0]-leaves[1]-...-leaves[L-1]-leaves[0]
    // Build adjacency for ring
    vector<int>ring_next(N+1,-1),ring_prev(N+1,-1);
    for(int i=0;i<L;i++){
        int a=leaves[i],b=leaves[(i+1)%L];
        ring_next[a]=b; ring_prev[b]=a;
    }
    // Tree decomposition bags and tree edges
    vector<vector<int>>bags;
    vector<vector<int>>adj;
    auto addBag=[&](vector<int>b)->int{
        int id=bags.size();
        bags.push_back(b);
        adj.push_back({});
        return id;
    };
    auto addEdge=[&](int a,int b){
        adj[a].push_back(b);
        adj[b].push_back(a);
    };
    // For each internal node, fan out bags covering its children on the ring
    // Process bottom-up
    map<int,int>node_bag; // maps tree node -> a bag containing it
    function<int(int)>solve=[&](int u)->int{
        if(ch[u].empty()){
            // leaf - will be handled by parent
            return -1;
        }
        vector<int>child_bags;
        for(int c:ch[u]){
            int b=solve(c);
            if(b>=0)child_bags.push_back(b);
        }
        // Collect leaf children in ring order and internal children
        vector<int>lc; // leaf children in order they appear
        for(int c:ch[u])if(ch[c].empty())lc.push_back(c);
        // Create bags: for consecutive pairs of leaf children + u + parent
        int p=par[u];
        int prev_bag=-1;
        if(lc.size()>=2){
            for(int i=0;i<(int)lc.size()-1;i++){
                vector<int>bg={u,lc[i],lc[i+1]};
                if(p)bg.push_back(p);
                int bid=addBag(bg);
                if(prev_bag>=0)addEdge(prev_bag,bid);
                prev_bag=bid;
            }
        } else if(lc.size()==1){
            vector<int>bg={u,lc[0]};
            if(p)bg.push_back(p);
            prev_bag=addBag(bg);
        } else {
            vector<int>bg={u};
            if(p)bg.push_back(p);
            prev_bag=addBag(bg);
        }
        for(int cb:child_bags)addEdge(prev_bag,cb);
        node_bag[u]=prev_bag;
        return prev_bag;
    };
    solve(1);
    printf("%d\n",(int)bags.size());
    for(auto&b:bags){
        printf("%d",(int)b.size());
        for(int x:b)printf(" %d",x);
        printf("\n");
    }
    for(int i=0;i<(int)adj.size();i++)
        for(int j:adj[i])if(j>i)printf("%d %d\n",i+1,j+1);
}
